package io.coolbox.bandit;
import io.coolbox.internal.NativeHandle;import com.sun.jna.ptr.DoubleByReference;import io.coolbox.CoolBoxException;
/** A Bernoulli bandit arm (Python: {@code multi_arm_bandit.BanditArm}). */
public final class BanditArm extends NativeHandle {private static final BanditNative N=BanditNative.INSTANCE;public BanditArm(double trueRewardProbability){super(N.coolbox_bandit_arm_new(trueRewardProbability),N::coolbox_bandit_arm_free);}public double pull(){DoubleByReference r=new DoubleByReference();if(N.coolbox_bandit_arm_pull(handle(),r)==0)throw new CoolBoxException("bandit pull failed");return r.getValue();}public BanditArm update(double reward){if(N.coolbox_bandit_arm_update(handle(),reward)==0)throw new CoolBoxException("bandit update failed");return this;}public double estimatedProbability(){return N.coolbox_bandit_arm_estimated_probability(handle());}public int pullCount(){return N.coolbox_bandit_arm_pull_count(handle());}public double trueProbability(){return N.coolbox_bandit_arm_true_probability(handle());}}
